CREATE TABLE IF NOT EXISTS events (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), title TEXT NOT NULL, day DATE NOT NULL, annual BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS memories (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, day DATE NOT NULL, photo_id INT REFERENCES photos(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS wishes (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), title TEXT NOT NULL, category TEXT NOT NULL, done BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS letters (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id), recipient_id INT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, opens_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS letter_hidden (letter_id INT REFERENCES letters(id) ON DELETE CASCADE, user_id INT REFERENCES users(id), PRIMARY KEY(letter_id,user_id));
CREATE TABLE IF NOT EXISTS reactions (target TEXT NOT NULL, target_id INT NOT NULL, user_id INT NOT NULL REFERENCES users(id), emoji TEXT NOT NULL, PRIMARY KEY(target,target_id,user_id));
